package mx.taller.client;
import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
import mx.taller.workshop.TallerRepository;
import mx.taller.vehicle.VehiculoRepository;
@RestController @RequestMapping("/api/clientes") public class ClienteController {
 private final ClienteRepository repo; private final TallerRepository talleres; private final VehiculoRepository vehiculos; public ClienteController(ClienteRepository r,TallerRepository t,VehiculoRepository v){repo=r;talleres=t;vehiculos=v;}
 @GetMapping("/opciones") @PreAuthorize("hasAnyRole('ADMINISTRADOR_TALLER','RECEPCIONISTA')") public Page<Map<String,Object>> opciones(@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="0") int page){return repo.buscarActivos(q.trim(),PageRequest.of(Math.max(0,page),10,Sort.by(Sort.Direction.ASC,"nombre"))).map(c->Map.<String,Object>of("id",c.getId(),"nombre",c.getNombre()+" "+c.getApellido(),"email",c.getEmail(),"telefono",c.getTelefono()));}
 @GetMapping("/inactivos") @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") public Page<ClienteResumenDto> inactivos(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(defaultValue="nombre") String sort,@RequestParam(defaultValue="asc") String dir){if(!Set.of("nombre","apellido","email","telefono").contains(sort))sort="nombre";return repo.findByActivoFalse(PageRequest.of(Math.max(0,page),Math.min(10,Math.max(1,size)),Sort.by("desc".equalsIgnoreCase(dir)?Sort.Direction.DESC:Sort.Direction.ASC,sort))).map(c->new ClienteResumenDto(c.getId(),c.getNombre(),c.getApellido(),c.getEmail(),c.getTelefono(),vehiculos.countByClienteIdAndActivoTrue(c.getId())));}
 @GetMapping @PreAuthorize("hasAnyRole('ADMINISTRADOR_TALLER','RECEPCIONISTA','MECANICO')") public Page<ClienteResumenDto> listar(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(defaultValue="nombre") String sort,@RequestParam(defaultValue="asc") String dir){if(!Set.of("nombre","apellido","email","telefono").contains(sort))sort="nombre";return repo.findByActivoTrue(PageRequest.of(Math.max(0,page),Math.min(10,Math.max(1,size)),Sort.by("desc".equalsIgnoreCase(dir)?Sort.Direction.DESC:Sort.Direction.ASC,sort))).map(c->new ClienteResumenDto(c.getId(),c.getNombre(),c.getApellido(),c.getEmail(),c.getTelefono(),vehiculos.countByClienteIdAndActivoTrue(c.getId())));}
 @PostMapping @PreAuthorize("hasAnyRole('ADMINISTRADOR_TALLER','RECEPCIONISTA')") public Cliente crear(@Valid @RequestBody ClienteDto d){var taller=talleres.findFirstByActivoTrue().orElseThrow(()->new IllegalArgumentException("Primero debe configurarse el taller"));if(repo.existsByEmailIgnoreCase(d.email()))throw new IllegalArgumentException("Email duplicado");if(repo.existsByTelefono(d.telefono()))throw new IllegalArgumentException("Teléfono duplicado");return repo.save(new Cliente(taller,d.nombre(),d.apellido(),d.email(),d.telefono()));}
 @PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMINISTRADOR_TALLER','RECEPCIONISTA')") public Cliente editar(@PathVariable UUID id,@Valid @RequestBody ClienteDto d){Cliente c=repo.findByIdAndActivoTrue(id).orElseThrow(()->new IllegalArgumentException("Cliente no encontrado"));if(repo.existsByEmailIgnoreCase(d.email())&&!c.getEmail().equalsIgnoreCase(d.email()))throw new IllegalArgumentException("Email duplicado");if(repo.existsByTelefono(d.telefono())&&!c.getTelefono().equals(d.telefono()))throw new IllegalArgumentException("Teléfono duplicado");c.actualizar(d.nombre(),d.apellido(),d.email(),d.telefono());return repo.save(c);}
 @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") public void desactivar(@PathVariable UUID id){Cliente c=repo.findByIdAndActivoTrue(id).orElseThrow(()->new IllegalArgumentException("Cliente no encontrado"));c.setActivo(false);repo.save(c);}
 @PatchMapping("/{id}/reactivar") @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") public Map<String,String> reactivar(@PathVariable UUID id){Cliente c=repo.findByIdAndActivoFalse(id).orElseThrow(()->new IllegalArgumentException("Cliente inactivo no encontrado"));c.setActivo(true);repo.save(c);return Map.of("mensaje","Cliente reactivado");}
 public record ClienteResumenDto(UUID id,String nombre,String apellido,String email,String telefono,long vehiculosActivos){}
}
